create or replace function public.has_valid_record_consent(p_patient_id uuid, p_doctor_id uuid) returns boolean language plpgsql stable security definer set search_path = public as $$ begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; return exists (select 1 from public.record_consents rc join public.doctors d on d.id = rc.doctor_id where rc.patient_id = p_patient_id and rc.doctor_id = p_doctor_id and d.approval_status = 'APPROVED' and rc.status = 'ACTIVE' and (rc.expires_at is null or rc.expires_at > now())); end; $$;
